import sys,re,urllib.request,urllib.parse
B='http://127.0.0.1:19770'
def post(path,data):
    r=urllib.request.urlopen(urllib.request.Request(B+path,urllib.parse.urlencode(data).encode()))
    return r.read().decode()
def get(path): return urllib.request.urlopen(B+path).read().decode()
def vs(h): return re.search(r'name="__VIEWSTATE" id="__VIEWSTATE" value="([^"]*)"',h).group(1)
def rows(h): return re.findall(r'<tr class="rgRow">(.*?)</tr>',h)
def cells(r): return [re.sub('<.*?>','',c) for c in re.findall(r'<td>(.*?)</td>',r)]
def filt(path,field,val):
    h=get(path)
    return post(path,{'__EVENTTARGET':'','__EVENTARGUMENT':'','__VIEWSTATE':vs(h),'fRes':'','fDir' if field=='fDir' else 'x':val,'fGo.x':'1','fGo.y':'1','fId':''})
if __name__=='__main__':
    path,val=sys.argv[1:3]
    h=filt(path,'fDir',val)
    for r in rows(h): print(cells(r)[:4])
    print(re.findall(r'class="rgPager".*?</tr>',h)[:1] and 'pager' )
EOF
cd /tmp/gate; for d in 1004 1011 1026; do echo == $d; python3 -I p.py /Residents.aspx $d; python3 -I p.py /Devices.aspx $d; done

